code='''import numpy as np,json,struct
with open("model.safetensors","rb") as f:
 n=struct.unpack("<Q",f.read(8))[0]; HEADER=json.loads(f.read(n)); OFFSET=8+n

def weight(k):
 h=HEADER[k]; a,b=h['data_offsets']; dt=h['dtype']
 if dt=='BF16':
  x=np.memmap('model.safetensors',mode='r',dtype=np.uint16,offset=OFFSET+a,shape=tuple(h['shape']))
  return (x.astype(np.uint32)<<16).view(np.float32)
 elif dt=='F32':
  return np.array(np.memmap('model.safetensors',mode='r',dtype=np.float32,offset=OFFSET+a,shape=tuple(h['shape'])))
 else: raise ValueError(dt)
'''
open('utils.py','w').write(code)
